    # Check if the function arguments are hashable and use them as key
    if _hashable(args) and (not kwds or _hashable(kwds)):
        return _make_key(func, args, kwds, typed)
    # Compute a unique key if arguments are not hashable
    hasher = hashlib.md5()
    hasher.update(func.__module__.encode('utf-8'))
    hasher.update(func.__name__.encode('utf-8'))
    hasher.update(pickle.dumps(args))
    hasher.update(pickle.dumps(kwds))
    return hasher.hexdigest()

