def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        if maxsize <= 0:
            raise ValueError('maxsize must be greater than 0')

        cache = {}
        frequency = {}
        _lock = Lock()
        min_freq = 1

        def access(key):
            nonlocal min_freq
            freq = frequency.get(key, 0)
            frequency[key] = freq + 1
            if freq == min_freq - 1:
                min_freq += 1
            return freq

        def evict():
            nonlocal min_freq
            while cache:
                key, (val, freq) = cache.popitem()
                if freq == min_freq:
                    del frequency[key]
                    break

        def wrapper(*args, **kwargs):
            key = (args, tuple(kwargs.items())) if typed else args
            freq = access(key)

            if key not in cache:
                evict()
                value = func(*args, **kwargs)
                cache[key] = (value, freq)
                min_freq = 1

            return cache[key][0]

        return wrapper

    return decorator

