def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent
    """
    if not all(issubclass(cls, (type,))
               for cls in classes):
        raise TypeError("All elements must be classes")

    base_to_subclasses = {}

    for cls in classes:
        for base in cls.__bases__:
            base_to_subclasses.setdefault(base, []).append(cls)

    visited = set()
    results = []

    while True:
        new_classes = []
        for cls in classes:
            all_bases_seen = all(base in visited for base in cls.__bases__)
            if all_bases_seen and cls not in visited:
                results.append(cls)
                visited.add(cls)

            for subcls in base_to_subclasses.get(cls, []):
                if subcls not in visited:
                    new_classes.append(subcls)

        if not new_classes:
            break

        classes = new_classes

    return results

