def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            files_dict = {}
            for file_info in zip_ref.infolist():
                file_name = file_info.filename
                if file_name.endswith('.xml'):
                    xml_base_name = os.path.splitext(file_name)[0]
                    if xml_base_name not in files_dict:
                        files_dict[xml_base_name] = []
                    files_dict[xml_base_name].append(zip_ref.read(file_name))
            return files_dict
    except Exception as e:
        print(f"Error exploring zip file: {e}")
        return {}

