def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    try:
        if verbose:
            print(f"Command: {commands} with args: {args}")

        import subprocess

        if hide_stderr:
            stderr = subprocess.STDOUT
        else:
            stderr = subprocess.PIPE

        args = args if args else []
        full_command = [commands] + args

        process = subprocess.Popen(full_command, cwd=cwd, env=env, stderr=stderr, stdout=subprocess.PIPE)
        stdout, stderr = process.communicate()

        if process.returncode != 0:
            if hide_stderr:
                error_message = stderr.decode().strip()
            else:
                error_message = f"Command failed: {commands} with args: {args}\nError: {stderr.decode().strip()}"
            if verbose:
                print(error_message)
            raise RuntimeError(error_message)

        if verbose:
            print(f"Output: {stdout.decode().strip()}")

        return stdout.decode().strip()

    except Exception as e:
        if verbose:
            print(f"An error occurred: {e}")
        raise e

