def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet cannot be empty")
    if not (1 <= len(alphabet) <= 36):
        raise ValueError("Alphabet must have between 1 and 36 characters")
    if base > 10 and not alphabet.isalnum():
        raise ValueError("Alphabet must be alphanumeric for bases greater than 10")
    base = len(alphabet)
    if number == 0:
        return alphabet[0] * (padding or 1)
    digits = []
    while number:
        digits.append(number % base)
        number //= base
    result = ''.join(alphabet[d] for d in reversed(digits))
    if padding:
        result = result.zfill(padding)
    return result

