def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = [cls]

    while queue:
        c = queue.pop()
        seen.add(c)

        sc = c.__subclasses__()
        for s in sc:
            if s not in seen:
                queue.append(s)

    seen.remove(cls)
    return seen

