def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None
    if not isinstance(frequency, str):
        raise ValueError("Frequency must be a string")
    try:
        num, unit = frequency.split()
        num = int(num)
        if unit.endswith('s'):
            unit = unit[:-1]
        if unit == "seconds":
            return datetime.timedelta(seconds=num)
        elif unit == "minutes":
            return datetime.timedelta(minutes=num)
        elif unit == "hours":
            return datetime.timedelta(hours=num)
        elif unit == "days":
            return datetime.timedelta(days=num)
        elif unit == "weeks":
            return datetime.timedelta(weeks=num)
        else:
            raise ValueError("Invalid time unit: {}".format(unit))
    except (ValueError, AttributeError):
        raise ValueError("Unable to parse frequency: {}".format(frequency))

