def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.'''
    from logging import LogRecord
    import json
    import os
    import toml

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        try:
            if not os.path.exists(filename):
                log_records.append(LogRecord('load_configurations', logging.ERROR, filename, None, 'Config file not found: %(filename)s', {'filename': filename}, None))
                continue

            with open(filename, 'r') as fd:
                raw_config = fd.read()

            if filename.endswith('.json'):
                config = json.loads(raw_config)
            elif filename.endswith('.toml'):
                config = toml.loads(raw_config)
            else:
                log_records.append(LogRecord('load_configurations', logging.ERROR, filename, None, 'Unsupported file format: %(filename)s', {'filename': filename}, None))
                continue

            if resolve_env:
                import os
                config = {k: v % os.environ if isinstance(v, str) and '${' in v else v for k, v in config.items()}

            config_dict[filename] = config
        except Exception as e:
            log_records.append(LogRecord('load_configurations', logging.ERROR, filename, None, 'Error Parsing Config File: %(filename)s - %(error)s', {'filename': filename, 'error': str(e)}, None))

    return config_dict, log_records

