def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type

    Args:
        settings_dirs (list): List of directories to search for files.
        spec_option (str): Specification option for file filtering.

    Returns:
        list: List of file names matching the spec_option.

    Raises:
        ValueError: If spec_option is not valid.
    """
    if spec_option not in ['python', 'ini']:
        raise ValueError("Invalid spec_option. Supported options are 'python' and 'ini'.")

    matching_files = []
    for directory in settings_dirs:
        try:
            for root, _, files in os.walk(directory):
                for file in files:
                    if spec_option == 'python' and file.endswith('.py'):
                        matching_files.append(os.path.join(root, file))
                    elif spec_option == 'ini' and file.endswith('.ini'):
                        matching_files.append(os.path.join(root, file))
        except PermissionError:
            continue

    return matching_files

