def _include_groups(self, parser_dict):
    """
    Resolves the include dict directive in the spec files.
    """
    resolved_dict = {}
    for key, value in parser_dict.items():
        if value and isinstance(value, dict) and 'include' in value:
            include_path = value['include']
            try:
                with open(include_path, 'r') as file:
                    include_dict = file.read()
                    include_dict = eval(include_dict)  # Be cautious with eval
                    include_dict.pop('include', None)  # Remove the include directive
                    resolved_dict.update(include_dict)
            except (FileNotFoundError, SyntaxError) as e:
                print(f"Error including {include_path}: {e}")
        else:
            resolved_dict[key] = value
